from dataclasses import dataclass

@dataclass
class DiscountCode:
    code: str
    discount_percentage: float

discount_codes = {
    'SAVE10': DiscountCode('SAVE10', 0.10),
    'SAVE20': DiscountCode('SAVE20', 0.20),
    'HALFOFF': DiscountCode('HALFOFF', 0.50),
}

class Cart:
    def __init__(self):
        self.items = []
        self.discount_code = None

    def add_item(self, name, price, qty):
        self.items.append({'name': name, 'price': price, 'qty': qty})

    @property
    def subtotal(self):
        return sum(item['price'] * item['qty'] for item in self.items)

    @property
    def discount(self):
        if self.discount_code:
            return self.subtotal * discount_codes[self.discount_code].discount_percentage
        return 0

    @property
    def tax(self):
        return (self.subtotal - self.discount) * 0.08

    @property
    def total(self):
        return self.subtotal - self.discount + self.tax
